public class Main {
    static void fun(int n) {
        if(n == 0) {
            return;
        }
        System.out.print(n + " ");
        fun(n - 1);
        System.out.print(n + " ");
    }

    public static void main(String[] args) {
        fun(3);
    }
}

public class Main {
    static int mystery(int n) {
        return n + mystery(n - 1);
    }

    public static void main(String[] args) {
        System.out.println(mystery(5));
    }
}

public class Main {
    static boolean isEven(int n) {
        if(n == 0) {
            return true;
        }
        return isOdd(n - 1);
    }

    static boolean isOdd(int n) {
        if(n == 0) {
            return false;
        }
        return isEven(n - 1);
    }

    public static void main(String[] args) {
        System.out.println(isEven(7));
        System.out.println(isOdd(4));
    }
}

public class Main {
    static void shout(String s) {
        if(s.length() == 0) {
            return;
        }
        shout(s.substring(1));
        System.out.print(s.charAt(0));
    }

    public static void main(String[] args) {
        shout("java");
    }
}

public class Main {
    static int grow(int n) {
        if(n >= 3) {
            return n;
        }
        int r = grow(n + 1) + n;
        System.out.print(r + " ");
        return r;
    }

    public static void main(String[] args) {
        System.out.println(grow(1));
    }
}

public class Main {
    static void split(int n) {
        if(n == 0) {
            System.out.print("*");
            return;
        }
        split(n - 1);
        split(n - 1);
    }

    public static void main(String[] args) {
        split(3);
    }
}

public class Main {
    static String build(int n) {
        if(n == 0) {
            return "";
        }
        String rest = build(n - 1);
        return rest + n + rest;
    }

    public static void main(String[] args) {
        System.out.println(build(3));
    }
}
